      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommSemiring R] (p q : Polynomial R) {r : R} [NoZeroDivisors R],\n  p ∣ q → p.scaleRoots r ∣ q.scaleRoots r"
    },
    {
      "name": "Polynomial.coeff_scaleRoots",
      "module_name": "Mathlib.RingTheory.Polynomial.ScaleRoots",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (p : Polynomial R) (s : R) (i : ℕ),\n  (p.scaleRoots s).coeff i = p.coeff i * s ^ (p.natDegree - i)"
    },
    {
      "name": "Polynomial.monic_scaleRoots_iff",
      "module_name": "Mathlib.RingTheory.Polynomial.ScaleRoots",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] {p : Polynomial R} (s : R), (p.scaleRoots s).Monic ↔ p.Monic"
    },
    {
      "name": "Polynomial.degree_scaleRoots",
      "module_name": "Mathlib.RingTheory.Polynomial.ScaleRoots",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (p : Polynomial R) {s : R}, (p.scaleRoots s).degree = p.degree"
    }
  ]
}

